const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict'),cp=require('node:child_process');
const b=JSON.parse(fs.readFileSync('data/million-city-launch-20261102/preservation-baseline.json'));let checked=0;
for(const [file,hash]of Object.entries(b.hashes)){if(file==='public/android.html'){const old=cp.execFileSync('git',['show',b.commit+':'+file],{encoding:'utf8'});const clean=s=>s.replace(/\?v=[^"'<>\s]+/g,'?v=CACHE');assert.equal(clean(fs.readFileSync(file,'utf8')),clean(old),'APK download page changed beyond asset cache stamps');continue;}assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'),hash,'Preserve existing data/model/release: '+file);checked++;}
const ids=JSON.parse(fs.readFileSync('public/city-picker.json')).cities.map(c=>c.id);assert.equal(ids.length,95);for(const id of b.cityIds)assert(ids.includes(id));console.log('PASS: '+checked+' original catalogue/model/release hashes preserved; Android page only cache stamps; all91priorcities retained.');
